$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'ESAgentLoopAdapters.psm1') -Force;$c=[Collections.Generic.List[object]]::new();function C($n,$b){[void]$c.Add([pscustomobject]@{case=$n;status=$(if($b){'passed'}else{'failed'})})}
$s=New-ESOpenHandsConversation -ConversationId 'conv-1' -TaskId 'task-1';$s=Set-ESOpenHandsEnvironment $s $true;$s=Invoke-ESOpenHandsStep $s observe;$s=Invoke-ESOpenHandsStep $s decide;$s=Invoke-ESOpenHandsStep $s tool read 'source';$s=Invoke-ESOpenHandsStep $s verify;C 'agent-loop' ($s.status -eq 'verified');try{Invoke-ESOpenHandsStep $s tool shell 'x';C 'tool-denied' $false}catch{C 'tool-denied' $true};$ok=Invoke-ESSweAgentPatchTest -RepositoryRoot 'repo' -Patch 'diff' -EnvironmentTrusted $true -Test { $true };C 'patch-test' ($ok.testStatus -eq 'passed');try{Invoke-ESSweAgentPatchTest -RepositoryRoot 'repo' -Patch 'diff' -EnvironmentTrusted $false -Test { $true };C 'environment-untrusted' $false}catch{C 'environment-untrusted' $true};try{Invoke-ESSweAgentPatchTest -RepositoryRoot 'repo' -Patch '' -EnvironmentTrusted $true -Test { $true };C 'invalid-patch' $false}catch{C 'invalid-patch' $true};try{Invoke-ESSweAgentPatchTest -RepositoryRoot 'repo' -Patch 'diff' -EnvironmentTrusted $true -Test { $false };C 'test-failed' $false}catch{C 'test-failed' $true};$f=@($c|? status -eq 'failed');[pscustomobject]@{schemaVersion=1;validator='Test-ESAgentLoopAdapters';status=$(if($f.Count){'failed'}else{'passed'});caseCount=$c.Count;passedCount=@($c|? status -eq 'passed').Count;failedCount=$f.Count;cases=@($c);runtimeStatus='runtime-not-run';claimsNotProven=@('External OpenHands/SWE-agent runtime equivalence','Unity/host runtime')}|ConvertTo-Json -Depth 10;if($f.Count){exit 1}
